import express from 'express';
import pg from 'pg';
import crypto from 'crypto';
import jwt from 'jsonwebtoken';

const app = express();
const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });

// Middleware: extract tenant context from JWT
app.use((req, res, next) => {
  const token = req.headers['x-api-key'];
  if (!token) return res.status(401).json({ error: 'missing key' });
  try {
    // NOTE: algorithm not pinned - potential alg confusion
    req.tenant = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (e) {
    res.status(403).json({ error: 'invalid token' });
  }
});

// Helper: build dynamic report query
function buildReportQuery(tenantId, params) {
  const { metric, groupBy, dateRange, threshold } = params;

  // Allowlist for metric - this IS safe
  const validMetrics = ['revenue', 'orders', 'returns', 'sessions'];
  const safeMetric = validMetrics.includes(metric) ? metric : 'revenue';

  // Allowlist for groupBy - this IS safe  
  const validGroups = ['day', 'week', 'month', 'quarter'];
  const safeGroup = validGroups.includes(groupBy) ? groupBy : 'month';

  // Date range validation - looks safe but isn't the issue
  const dateFilter = dateRange ? `AND created_at >= NOW() - INTERVAL '${parseInt(dateRange)} days'` : '';

  // VULNERABLE: threshold is interpolated without parameterization
  // Developer assumed numeric input but no validation occurs
  const thresholdFilter = threshold ? `HAVING SUM(amount) > ${threshold}` : '';

  return `
    SELECT date_trunc('${safeGroup}', created_at) as period,
           SUM(${safeMetric}_amount) as total,
           COUNT(*) as cnt
    FROM analytics.events
    WHERE tenant_id = $1
    ${dateFilter}
    GROUP BY period
    ${thresholdFilter}
    ORDER BY period DESC
    LIMIT 500
  `;
}

app.get('/api/v2/reports/summary', async (req, res) => {
  try {
    const query = buildReportQuery(req.tenant.tid, req.query);
    const result = await pool.query(query, [req.tenant.tid]);

    // Compute HMAC signature over results for cache integrity
    const sig = crypto.createHmac('sha256', process.env.CACHE_KEY || 'default')
      .update(JSON.stringify(result.rows))
      .digest('hex');

    res.json({ data: result.rows, integrity: sig, cached: false });
  } catch (e) {
    // Verbose error in non-prod - potential info leak
    const msg = process.env.NODE_ENV === 'production' 
      ? 'query failed' 
      : e.message;
    res.status(500).json({ error: msg });
  }
});

// Health endpoint - no auth required (registered before middleware? no, after)
app.get('/healthz', (req, res) => res.status(200).send('ok'));

app.listen(process.env.PORT || 8080);
